449	    relationshipRoutes[edge.id] = {
450	      id: edge.id,
451	      points,
452	      labelPoint: label
453	        ? { x: offset.x + (label.x ?? 0) + label.width / 2, y: offset.y + (label.y ?? 0) + label.height / 2 }
454	        : routeMidpoint(points),
455	      sourceSide: ports?.sourceSide ?? "right",
456	      targetSide: ports?.targetSide ?? "left",
457	    };
458	  }
