import { indexSemanticGraph, type SemanticGraph } from "./semantic-graph";

export type CanvasMode = "browse" | "inspect" | "focus" | "trace";

export type SemanticZoomLevel = "landscape" | "architecture" | "component" | "operational";

export type CanvasSelection =
  | { kind: "object"; id: string }
  | { kind: "relationship"; id: string }
  | { kind: "flow"; id: string }
  | null;

export type ObjectEmphasis = "primary" | "related" | "context" | "normal" | "muted";

export type RelationshipEmphasis = "active" | "related" | "normal" | "muted" | "suppressed";

export type RegionEmphasis = "active" | "normal" | "muted";

export type CanvasInteractionState = {
  mode: CanvasMode;
  selection: CanvasSelection;
  activeFlowId: string | null;
  zoom: number;
  searchQuery: string;
};

export type CanvasViewModel = {
  mode: CanvasMode;
  selection: CanvasSelection;
  activeFlowId: string | null;
  zoom: number;
  zoomLevel: SemanticZoomLevel;
  objectEmphasis: Map<string, ObjectEmphasis>;
  relationshipEmphasis: Map<string, RelationshipEmphasis>;
  regionEmphasis: Map<string, RegionEmphasis>;
  searchMatches: Set<string>;
  focusObjectIds: Set<string>;
  activeRelationshipIds: Set<string>;
};

export function semanticZoomLevel(zoom: number): SemanticZoomLevel {
  if (zoom < 0.48) return "landscape";
  if (zoom < 0.8) return "architecture";
  if (zoom < 1.22) return "component";
  return "operational";
}

function adjacentObjectId(sourceObjectId: string, targetObjectId: string, objectId: string) {
  return sourceObjectId === objectId ? targetObjectId : sourceObjectId;
}

function neighbors(graph: SemanticGraph, objectIds: Set<string>) {
  const result = new Set<string>();
  for (const relationship of graph.relationships) {
    if (objectIds.has(relationship.sourceObjectId)) result.add(relationship.targetObjectId);
    if (objectIds.has(relationship.targetObjectId)) result.add(relationship.sourceObjectId);
  }
  return result;
}

export function deriveCanvasView(graph: SemanticGraph, interaction: CanvasInteractionState): CanvasViewModel {
  const index = indexSemanticGraph(graph);
  const objectEmphasis = new Map(graph.objects.map((object) => [object.id, "normal" as ObjectEmphasis]));
  const relationshipEmphasis = new Map(graph.relationships.map((relationship) => [relationship.id, "normal" as RelationshipEmphasis]));
  const regionEmphasis = new Map(graph.regions.map((region) => [region.id, "normal" as RegionEmphasis]));
  const focusObjectIds = new Set<string>();
  const activeRelationshipIds = new Set<string>();
  const query = interaction.searchQuery.trim().toLowerCase();
  const searchMatches = new Set(
    query
      ? graph.objects
        .filter((object) => `${object.name} ${object.summary ?? ""} ${object.objectType} ${String(object.metadata.technology ?? "")}`.toLowerCase().includes(query))
        .map((object) => object.id)
      : graph.objects.map((object) => object.id),
  );

  if (query) {
    for (const object of graph.objects) objectEmphasis.set(object.id, searchMatches.has(object.id) ? "related" : "muted");
    for (const relationship of graph.relationships) {
      if (!searchMatches.has(relationship.sourceObjectId) && !searchMatches.has(relationship.targetObjectId)) relationshipEmphasis.set(relationship.id, "muted");
    }
  }

  if (interaction.mode === "inspect" && interaction.selection?.kind === "object") {
    const selectedId = interaction.selection.id;
    focusObjectIds.add(selectedId);
    objectEmphasis.set(selectedId, "primary");
    const incident = [
      ...(index.incomingByObjectId.get(selectedId) ?? []),
      ...(index.outgoingByObjectId.get(selectedId) ?? []),
    ];
    for (const relationship of incident) {
      relationshipEmphasis.set(relationship.id, "active");
      activeRelationshipIds.add(relationship.id);
      const adjacentId = adjacentObjectId(relationship.sourceObjectId, relationship.targetObjectId, selectedId);
      if (adjacentId !== selectedId) objectEmphasis.set(adjacentId, "related");
    }
  }

  if (interaction.mode === "inspect" && interaction.selection?.kind === "relationship") {
    const selected = index.relationshipById.get(interaction.selection.id);
    if (selected) {
      relationshipEmphasis.set(selected.id, "active");
      activeRelationshipIds.add(selected.id);
      objectEmphasis.set(selected.sourceObjectId, "primary");
      objectEmphasis.set(selected.targetObjectId, "primary");
      focusObjectIds.add(selected.sourceObjectId);
      focusObjectIds.add(selected.targetObjectId);
    }
  }

  if (interaction.mode === "focus" && interaction.selection?.kind === "object") {
    const selectedId = interaction.selection.id;
    const directIds = neighbors(graph, new Set([selectedId]));
    const secondHopIds = neighbors(graph, directIds);
    const selectedRegionId = index.objectById.get(selectedId)?.regionId;
    for (const object of graph.objects) {
      if (object.id === selectedId) objectEmphasis.set(object.id, "primary");
      else if (directIds.has(object.id)) objectEmphasis.set(object.id, "related");
      else if (secondHopIds.has(object.id) || object.regionId === selectedRegionId) objectEmphasis.set(object.id, "context");
      else objectEmphasis.set(object.id, "muted");
    }
    focusObjectIds.add(selectedId);
    for (const id of directIds) focusObjectIds.add(id);
    for (const relationship of graph.relationships) {
      if (relationship.sourceObjectId === selectedId || relationship.targetObjectId === selectedId) {
        relationshipEmphasis.set(relationship.id, "active");
        activeRelationshipIds.add(relationship.id);
      } else if (
        directIds.has(relationship.sourceObjectId)
        && (secondHopIds.has(relationship.targetObjectId) || directIds.has(relationship.targetObjectId))
      ) {
        relationshipEmphasis.set(relationship.id, "related");
      } else {
        relationshipEmphasis.set(relationship.id, "muted");
      }
    }
  }

  if (interaction.mode === "trace" && interaction.activeFlowId) {
    const flow = index.flowById.get(interaction.activeFlowId);
    const flowObjectIds = new Set(flow?.objectIds ?? []);
    const flowRelationshipIds = new Set(flow?.relationshipIds ?? []);
    const contextIds = neighbors(graph, flowObjectIds);
    for (const object of graph.objects) {
      if (flowObjectIds.has(object.id)) objectEmphasis.set(object.id, "primary");
      else if (contextIds.has(object.id)) objectEmphasis.set(object.id, "context");
      else objectEmphasis.set(object.id, "muted");
    }
    for (const objectId of flowObjectIds) focusObjectIds.add(objectId);
    for (const relationship of graph.relationships) {
      if (flowRelationshipIds.has(relationship.id)) {
        relationshipEmphasis.set(relationship.id, "active");
        activeRelationshipIds.add(relationship.id);
      } else if (flowObjectIds.has(relationship.sourceObjectId) || flowObjectIds.has(relationship.targetObjectId)) {
        relationshipEmphasis.set(relationship.id, "related");
      } else {
        relationshipEmphasis.set(relationship.id, "suppressed");
      }
    }
  }

  const activeRegionIds = new Set<string>();
  for (const object of graph.objects) {
    const emphasis = objectEmphasis.get(object.id);
    if (["primary", "related", "context"].includes(emphasis ?? "")) activeRegionIds.add(object.regionId);
  }
  if (["focus", "trace"].includes(interaction.mode)) {
    for (const region of graph.regions) regionEmphasis.set(region.id, activeRegionIds.has(region.id) ? "active" : "muted");
  }

  return {
    mode: interaction.mode,
    selection: interaction.selection,
    activeFlowId: interaction.activeFlowId,
    zoom: interaction.zoom,
    zoomLevel: semanticZoomLevel(interaction.zoom),
    objectEmphasis,
    relationshipEmphasis,
    regionEmphasis,
    searchMatches,
    focusObjectIds,
    activeRelationshipIds,
  };
}

export function visibleObjectIds(graph: SemanticGraph, view: CanvasViewModel) {
  if (view.zoomLevel !== "landscape") return new Set(graph.objects.map((object) => object.id));
  return new Set(graph.objects
    .filter((object) => {
      const emphasis = view.objectEmphasis.get(object.id) ?? "normal";
      const important = object.importance.level === "critical" || object.importance.level === "high";
      if (view.mode === "trace") return important || emphasis === "primary" || emphasis === "related";
      if (view.mode === "focus") return important || emphasis === "primary" || emphasis === "related";
      if (view.searchMatches.size < graph.objects.length) return important || view.searchMatches.has(object.id);
      return important || emphasis === "primary" || emphasis === "related";
    })
    .map((object) => object.id));
}

