45	function revisionSnapshot<T extends { validFromRevision: number; validToRevision: number | null; lifecycleStatus: string }>(
46	  rows: T[],
47	  revision: number,
48	  currentRevision: number,
49	) {
50	  if (revision === currentRevision) return rows.filter((row) => row.lifecycleStatus === "ACTIVE");
51	  return atRevision(rows.filter((row) => row.lifecycleStatus !== "PENDING"), revision);
52	}
