56	    && left.summary === right.summary
57	    && left.entityType === right.entityType
58	    && left.parentEntityKey === right.parentEntityKey
59	    && left.technology === right.technology
60	    && left.repositoryRefsJson === right.repositoryRefsJson
61	    && left.knowledgeState === right.knowledgeState;
