3	import {
4	  BaseEdge,
5	  EdgeLabelRenderer,
6	  getSmoothStepPath,
7	  type Edge,
8	  type EdgeProps,
9	} from "@xyflow/react";
10	import { useSmartEdgePath } from "@tisoap/react-flow-smart-edge";
11	import type { RelationshipEdgeData } from "./types";
12	
13	export type ArchitectureFlowEdge = Edge<RelationshipEdgeData, "relationship">;
14	
15	function roundedOrthogonalPath(points: Array<{ x: number; y: number }>, radius = 8) {
16	  if (points.length < 2) return "";
17	  let path = `M ${points[0].x} ${points[0].y}`;
18	  for (let index = 1; index < points.length - 1; index += 1) {
19	    const previous = points[index - 1];
20	    const current = points[index];
21	    const next = points[index + 1];
22	    const incomingLength = Math.hypot(current.x - previous.x, current.y - previous.y);
23	    const outgoingLength = Math.hypot(next.x - current.x, next.y - current.y);
24	    const corner = Math.min(radius, incomingLength / 2, outgoingLength / 2);
25	    if (!corner || (previous.x === current.x && current.x === next.x) || (previous.y === current.y && current.y === next.y)) {
26	      path += ` L ${current.x} ${current.y}`;
27	      continue;
28	    }
29	    const before = {
30	      x: current.x - ((current.x - previous.x) / incomingLength) * corner,
31	      y: current.y - ((current.y - previous.y) / incomingLength) * corner,
32	    };
33	    const after = {
34	      x: current.x + ((next.x - current.x) / outgoingLength) * corner,
35	      y: current.y + ((next.y - current.y) / outgoingLength) * corner,
36	    };
37	    path += ` L ${before.x} ${before.y} Q ${current.x} ${current.y} ${after.x} ${after.y}`;
38	  }
39	  const last = points.at(-1)!;
40	  return `${path} L ${last.x} ${last.y}`;
41	}
42	
43	export default function RelationshipEdge(props: EdgeProps<ArchitectureFlowEdge>) {
44	  const smart = useSmartEdgePath({
45	    id: props.id,
46	    source: props.source,
47	    target: props.target,
48	    sourceX: props.sourceX,
49	    sourceY: props.sourceY,
50	    targetX: props.targetX,
51	    targetY: props.targetY,
52	    sourcePosition: props.sourcePosition,
53	    targetPosition: props.targetPosition,
54	    preset: "smoothstep",
55	    options: { gridRatio: 10, nodePadding: 18, borderRadius: 8 },
56	  });
57	  const fallback = getSmoothStepPath({
58	    sourceX: props.sourceX,
59	    sourceY: props.sourceY,
60	    sourcePosition: props.sourcePosition,
61	    targetX: props.targetX,
62	    targetY: props.targetY,
63	    targetPosition: props.targetPosition,
64	    borderRadius: 8,
65	  });
66	  const elkPath = props.data?.route?.points && props.data.route.points.length >= 2
67	    ? roundedOrthogonalPath(props.data.route.points)
68	    : "";
69	  const path = elkPath || (smart.route?.kind === "routed" ? smart.route.svgPathString : fallback[0]);
70	  const labelX = props.data?.route?.labelPoint?.x ?? (smart.route?.kind === "routed" ? smart.route.edgeCenterX : fallback[1]);
71	  const labelY = props.data?.route?.labelPoint?.y ?? (smart.route?.kind === "routed" ? smart.route.edgeCenterY : fallback[2]);
72	  const relationship = props.data?.relationship;
73	  const emphasis = props.data?.emphasis ?? "normal";
74	  const showLabel = emphasis === "active" || props.selected || props.data?.zoomLevel === "operational";
75	  const label = props.data?.flowPayload || relationship?.label || relationship?.relationshipType;
76	  const animate = emphasis === "active" && Boolean(props.data?.activeFlowName);
77	
78	  return (
79	    <g className={`relationship-edge type-${relationship?.relationshipType ?? "dependency"} emphasis-${emphasis} ${props.selected ? "is-selected" : ""}`}>
80	      <BaseEdge
81	        id={props.id}
82	        interactionWidth={22}
83	        markerEnd={props.markerEnd}
84	        path={path}
85	        style={props.style}
86	      />
87	      {animate && (
88	        <circle className="flow-packet" r="4.5">
89	          <animateMotion dur="2.8s" path={path} repeatCount="indefinite" />
90	        </circle>
91	      )}
92	      {showLabel && label && (
93	        <EdgeLabelRenderer>
94	          <div
95	            className={`relationship-label nodrag nopan ${emphasis === "active" ? "active" : ""}`}
96	            style={{ transform: `translate(-50%, -50%) translate(${labelX}px,${labelY}px)` }}
97	            title={relationship?.summary || relationship?.label}
98	          >
99	            {props.data?.flowSequence !== undefined && <b>{props.data.flowSequence}</b>}
100	            <span>{label}</span>
101	          </div>
102	        </EdgeLabelRenderer>
103	      )}
104	    </g>
105	  );
106	}
