import type { ObjectEmphasis, RegionEmphasis, RelationshipEmphasis, SemanticZoomLevel } from "./interaction";
import type { RelationshipRoute } from "./layout";
import type { SemanticObject, SemanticRegion, SemanticRelationship } from "./semantic-graph";

export type CatalogProject = {
  id: string;
  name: string;
  description: string;
  repositoryRef: string;
  defaultBranch: string;
  projectCategory: string;
  registryVisibility: string;
  revision: number;
  healthScore: number;
  alignmentScore: number;
  maintenanceMode: string;
  activeChanges: number;
  facts: number;
  unknowns: number;
  activeAgents: number;
  passedEvidence: number;
  architectureEntities: number;
  architectureFlows: number;
  updatedAt: string;
};

export type ArchitectureEntity = {
  id: string;
  projectId: string;
  changeId: string;
  entityKey: string;
  entityType: string;
  name: string;
  summary: string;
  parentEntityKey: string | null;
  technology: string;
  repositoryRefsJson: string;
  knowledgeState: string;
  lifecycleStatus: string;
  validFromRevision: number;
  validToRevision: number | null;
  sourceObservationId: string;
};

export type ArchitectureRelation = {
  id: string;
  projectId: string;
  changeId: string;
  relationKey: string;
  sourceEntityKey: string;
  targetEntityKey: string;
  relationType: string;
  label: string;
  summary: string;
  knowledgeState: string;
  evidenceRefsJson: string;
  lifecycleStatus: string;
  validFromRevision: number;
  validToRevision: number | null;
  sourceObservationId: string;
};

export type ArchitectureFlow = {
  id: string;
  projectId: string;
  changeId: string;
  flowKey: string;
  name: string;
  summary: string;
  trigger: string;
  outcome: string;
  knowledgeState: string;
  lifecycleStatus: string;
  validFromRevision: number;
  validToRevision: number | null;
  sourceObservationId: string;
};

export type ArchitectureFlowStep = {
  id: string;
  projectId: string;
  changeId: string;
  flowKey: string;
  stepKey: string;
  sequence: number;
  entityKey: string;
  role: string;
  title: string;
  inputsJson: string;
  action: string;
  outputsJson: string;
  stateReadsJson: string;
  stateWritesJson: string;
  failureModesJson: string;
  nextStepKeysJson: string;
  knowledgeState: string;
  lifecycleStatus: string;
  validFromRevision: number;
  validToRevision: number | null;
  sourceObservationId: string;
};

export type RelationshipEdgeData = Record<string, unknown> & {
  relationship: SemanticRelationship;
  route?: RelationshipRoute;
  emphasis: RelationshipEmphasis;
  zoomLevel: SemanticZoomLevel;
