  flowSequence?: number;
  flowPayload?: string;
};

export type ArchitectureEdgeData = RelationshipEdgeData;

export type ProjectDetail = {
  project: CatalogProject;
  architecture: {
    entities: ArchitectureEntity[];
    relations: ArchitectureRelation[];
