export const LAYOUT_ALGORITHM_VERSION = 2;

function composeTopLevelRegions(graph: SemanticGraph, layout: CanvasLayout): CanvasLayout {
  const rootRegions = graph.regions.filter((region) => !region.parentRegionId);
  if (rootRegions.length < 2) return layout;

  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  const objectRoot = new Map<string, string>();
  for (const root of rootRegions) {
    const regionIds = new Set<string>([root.id]);
    const queue = [root.id];
    while (queue.length > 0) {
      const current = queue.shift()!;
      for (const region of graph.regions) {
        if (region.parentRegionId === current && !regionIds.has(region.id)) {
          regionIds.add(region.id);
          queue.push(region.id);
        }
      }
    }
    for (const object of graph.objects) {
      if (regionIds.has(object.regionId)) objectRoot.set(object.id, root.id);
    }
  }

  const ordered = [...rootRegions].sort((left, right) => {
    const leftRect = layout.regionRects[left.id];
    const rightRect = layout.regionRects[right.id];
    const leftArea = (leftRect?.width ?? 0) * (leftRect?.height ?? 0);
    const rightArea = (rightRect?.width ?? 0) * (rightRect?.height ?? 0);
    return rightArea - leftArea || left.id.localeCompare(right.id);
  });

  const GAP = 76;
  const PADDING = 42;
  const columns = Math.max(1, Math.ceil(Math.sqrt(ordered.length)));
  const deltas = new Map<string, { dx: number; dy: number }>();
  let x = PADDING;
  let y = PADDING;
  let rowHeight = 0;
  ordered.forEach((region, index) => {
    const rect = layout.regionRects[region.id];
    if (!rect) return;
    deltas.set(region.id, { dx: x - rect.x, dy: y - rect.y });
    x += rect.width + GAP;
    rowHeight = Math.max(rowHeight, rect.height);
    if ((index + 1) % columns === 0) {
      x = PADDING;
      y += rowHeight + GAP;
      rowHeight = 0;
    }
  });

  const objectRects: Record<string, LayoutRect> = {};
  for (const [id, rect] of Object.entries(layout.objectRects)) {
    const delta = deltas.get(objectRoot.get(id) ?? "");
    objectRects[id] = delta ? { ...rect, x: rect.x + delta.dx, y: rect.y + delta.dy } : { ...rect };
  }
  const regionRects: Record<string, RegionLayoutRect> = {};
  for (const region of graph.regions) {
    const rect = layout.regionRects[region.id];
    if (!rect) continue;
    let cursor: string | undefined = region.id;
    while (cursor && !deltas.has(cursor)) cursor = regionById.get(cursor)?.parentRegionId;
    const delta = cursor ? deltas.get(cursor) : undefined;
    regionRects[region.id] = delta ? { ...rect, x: rect.x + delta.dx, y: rect.y + delta.dy } : { ...rect };
  }

  const relationshipRoutes: Record<string, RelationshipRoute> = {};
  for (const relationship of graph.relationships) {
    const route = layout.relationshipRoutes[relationship.id];
    if (!route) continue;
    const sourceRoot = objectRoot.get(relationship.sourceObjectId);
    const targetRoot = objectRoot.get(relationship.targetObjectId);
    const delta = sourceRoot && sourceRoot === targetRoot ? deltas.get(sourceRoot) : undefined;
    if (!delta) continue;
    relationshipRoutes[relationship.id] = {
      ...route,
      points: route.points.map((point) => ({ x: point.x + delta.dx, y: point.y + delta.dy })),
      labelPoint: route.labelPoint ? { x: route.labelPoint.x + delta.dx, y: route.labelPoint.y + delta.dy } : undefined,
    };
