"use client";

import type { CSSProperties } from "react";
import type { Node, NodeProps } from "@xyflow/react";
import { labelCompensation } from "./interaction";
import type { RegionNodeData } from "./types";

export type ArchitectureRegionNode = Node<RegionNodeData, "region">;

export default function RegionNode({ data }: NodeProps<ArchitectureRegionNode>) {
  const { region, emphasis, zoomLevel, zoom, objectCount, criticalCount, highCount, keyObjectNames, childRegionCount, depth } = data;
  const summary = zoomLevel === "landscape" || zoomLevel === "architecture";
  const labelScale = labelCompensation(zoomLevel, zoom);
  return (
    <section
      aria-label={`Region ${region.name}`}
      className={`canvas-region depth-${Math.min(depth, 3)} emphasis-${emphasis} zoom-${zoomLevel}`}
      style={{ "--label-scale": labelScale } as CSSProperties}
    >
      <header>
        <span>Region</span>
        <strong>{region.name}</strong>
        {!summary && <small>{objectCount} objects{childRegionCount > 0 ? ` · ${childRegionCount} regions` : ""}</small>}
      </header>
      {summary && (
        <p className="region-summary">
          <b>{objectCount} objects{criticalCount > 0 ? ` · ${criticalCount} critical` : ""}{highCount > 0 ? ` · ${highCount} high` : ""}</b>
          {keyObjectNames.length > 0 && <span>{keyObjectNames.join(" · ")}</span>}
        </p>
      )}
    </section>
  );
}

