```ts
export function defaultFocusRegion(graph: SemanticGraph, view: CanvasViewModel): string | null {
  const visible = visibleObjectIds(graph, view);
  let bestId: string | null = null;
  let bestScore = -1;
  for (const region of graph.regions) {
    let score = 0;
    let count = 0;
    for (const object of graph.objects) {
      if (object.regionId === region.id && visible.has(object.id)) {
        score += object.importance.score;
        count += 1;
      }
    }
    if (count === 0) continue;
    score += region.importance.score / 10;
    if (score > bestScore || (score === bestScore && bestId && region.id < bestId)) {
      bestScore = score;
      bestId = region.id;
    }
  }
  return bestId;
}
```

