const fitReadableMap = useCallback((duration: number) => {
  const instance = instanceRef.current;
  if (!instance) return;
  const targets = instance.getNodes().filter((node) => node.type === "object");
  const options = { ...fitViewContract(), padding: targets.length > 0 ? 0.24 : fitViewContract().padding, duration };
  if (targets.length > 0) void instance.fitView({ ...options, nodes: targets });
  else void instance.fitView(options);
}, []);

const fitOpeningFrame = useCallback((duration: number) => {
  const instance = instanceRef.current;
  if (!instance) return;
  const focusRegionId = defaultFocusRegion(graph, view);
  const visibleIds = visibleObjectIds(graph, view);
  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  const containsRegion = (objectId: string) => {
    let cursor = graph.objects.find((object) => object.id === objectId)?.regionId;
    const seen = new Set<string>();
    while (cursor && !seen.has(cursor)) {
      if (cursor === focusRegionId) return true;
      seen.add(cursor);
      cursor = regionById.get(cursor)?.parentRegionId;
    }
    return false;
  };
  const targets = instance.getNodes().filter((node) =>
    node.type === "region" && node.id === focusRegionId)
    ?? [];
  const objectTargets = instance.getNodes().filter((node) =>
    node.type === "object" && visibleIds.has(node.id) && containsRegion(node.id));
  const fitTargets = [...targets, ...objectTargets];
  if (fitTargets.length > 1) void instance.fitView({ ...fitViewContract(), padding: 0.14, duration, nodes: fitTargets });
  else fitReadableMap(duration);
}, [fitReadableMap, graph, view]);

useEffect(() => {
  setNodes(projection.nodes);
  setEdges(projection.edges);
  const layoutIdentity = layout ? `${storageKey}:${layout.fingerprint}` : "";
  if (layoutIdentity && fittedLayoutRef.current !== layoutIdentity) {
    fittedLayoutRef.current = layoutIdentity;
    const timer = window.setTimeout(() => fitOpeningFrame(360), 40);
    return () => window.clearTimeout(timer);
  }
  return undefined;
}, [fitOpeningFrame, layout, projection, setEdges, setNodes, storageKey]);

