() => new Promise((resolve) => setTimeout(() => {
  const select = document.querySelector("select[aria-label='Stress fixture']");
  const setter = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, "value").set;
  setter.call(select, "complex");
  select.dispatchEvent(new Event("change", { bubbles: true }));
  setTimeout(() => {
    const traceButton = [...document.querySelectorAll(".canvas-modes button")].find((button) => button.textContent.includes("Trace"));
    traceButton?.dispatchEvent(new MouseEvent("click", { bubbles: true }));
    setTimeout(() => {
      document.querySelector(".flow-lens-list button")?.dispatchEvent(new MouseEvent("click", { bubbles: true }));
      setTimeout(() => {
        const badges = [...document.querySelectorAll(".object-flow-steps span")];
        const labels = [...document.querySelectorAll(".relationship-label.active")];
        const edgePath = document.querySelector(".relationship-edge.emphasis-active .react-flow__edge-path");
        resolve({
          transform: document.querySelector(".react-flow__viewport").style.transform,
          badgeSizes: badges.slice(0, 4).map((badge) => { const r = badge.getBoundingClientRect(); return { text: badge.textContent.slice(0, 24), h: Math.round(r.height), effectiveFont: Math.round(parseFloat(getComputedStyle(badge).fontSize) * (badge.closest(".object-node")?.style.getPropertyValue("--label-scale") || 1) * 0.5) }; }),
          labelSizes: labels.slice(0, 4).map((label) => { const r = label.getBoundingClientRect(); return { text: label.textContent.slice(0, 26), h: Math.round(r.height) }; }),
          activeStroke: edgePath ? { width: getComputedStyle(edgePath).strokeWidth, vectorEffect: getComputedStyle(edgePath).vectorEffect } : null,
          corridorBar: document.querySelector(".trace-corridor-bar")?.textContent?.slice(0, 60),
        });
      }, 1000);
    }, 250);
  }, 2700);
}, 100))

