() => {
  const badge = document.querySelector(".object-flow-steps");
  const label = document.querySelector(".relationship-label.active");
  const inspect = (el, name) => {
    if (!el) return { name, found: false };
    const rect = el.getBoundingClientRect();
    const center = { x: Math.round(rect.x + rect.width / 2), y: Math.round(rect.y + rect.height / 2) };
    const top = document.elementFromPoint(center.x, center.y);
    return {
      name,
      found: true,
      rect: { x: Math.round(rect.x), y: Math.round(rect.y), w: Math.round(rect.width), h: Math.round(rect.height) },
      center,
      topElementAtPoint: top ? `${top.tagName}.${String(top.className).slice(0, 40)}` : "null",
      isSelf: top === el,
      display: getComputedStyle(el).display,
      opacity: getComputedStyle(el).opacity,
      parentOverflow: getComputedStyle(el.parentElement).overflow,
      ancestorOverflow: (() => { let node = el.parentElement; const chain = []; while (node && chain.length < 4) { chain.push(`${node.tagName}.${String(node.className).slice(0, 30)}:${getComputedStyle(node).overflow}`); node = node.parentElement; } return chain; })(),
    };
  };
  return [inspect(badge, "badge"), inspect(label, "payload-label")];
}

