"use client";

import { Handle, Position, type Node, type NodeProps } from "@xyflow/react";
import type { CSSProperties } from "react";
import { labelCompensation } from "./interaction";
import type { SemanticObjectType } from "./semantic-graph";
import type { ObjectNodeData } from "./types";

const TYPE_COPY: Record<SemanticObjectType, string> = {
  service: "Service",
  agent: "Agent",
  storage: "Storage",
  external: "External",
};

const POSITION: Record<"left" | "right" | "top" | "bottom", Position> = {
  left: Position.Left,
  right: Position.Right,
  top: Position.Top,
  bottom: Position.Bottom,
};

function ObjectTypeIcon({ type }: { type: SemanticObjectType }) {
  if (type === "storage") {
    return <svg aria-hidden="true" viewBox="0 0 20 20"><ellipse cx="10" cy="5" rx="6" ry="2.5" /><path d="M4 5v7.5C4 14 6.7 15 10 15s6-1 6-2.5V5" /><path d="M4 9c0 1.4 2.7 2.5 6 2.5S16 10.4 16 9" /></svg>;
  }
  if (type === "agent") {
    return <svg aria-hidden="true" viewBox="0 0 20 20"><circle cx="10" cy="6" r="3" /><path d="M4.5 16c.6-3.2 2.4-4.8 5.5-4.8s4.9 1.6 5.5 4.8" /><path d="M3 8h2M15 8h2" /></svg>;
  }
  if (type === "external") {
    return <svg aria-hidden="true" viewBox="0 0 20 20"><path d="M9 5H5v10h10v-4" /><path d="M10 10l6-6M11 4h5v5" /></svg>;
  }
  return <svg aria-hidden="true" viewBox="0 0 20 20"><rect x="4" y="4" width="12" height="12" rx="2" /><path d="M7 8h6M7 12h4" /></svg>;
}

export type ArchitectureFlowNode = Node<ObjectNodeData, "object">;

export default function ObjectNode({ data, selected }: NodeProps<ArchitectureFlowNode>) {
  const { object, emphasis, zoomLevel, zoom, incomingCount, outgoingCount, flowSteps } = data;
  const showState = zoomLevel !== "landscape";
  const showSummary = zoomLevel === "component" || zoomLevel === "operational";
  const showMetadata = zoomLevel === "operational";
  const labelScale = labelCompensation(zoomLevel, zoom);
  const technology = String(object.metadata.technology ?? "");

  return (
    <article
      aria-label={`${TYPE_COPY[object.objectType]} ${object.name}，${object.state.label}`}
      className={`object-node type-${object.objectType} emphasis-${emphasis} zoom-${zoomLevel} ${selected ? "is-selected" : ""}`}
      style={{ "--label-scale": labelScale } as CSSProperties}
    >
      {(["left", "right", "top", "bottom"] as const).flatMap((side) => [
        <Handle className="semantic-port" id={`target-${side}`} key={`target-${side}`} position={POSITION[side]} type="target" />,
        <Handle className="semantic-port" id={`source-${side}`} key={`source-${side}`} position={POSITION[side]} type="source" />,
      ])}
      <div className="object-surface">
        <header className="object-type-row">
          <span className="object-type-icon"><ObjectTypeIcon type={object.objectType} /></span>
          <span>{TYPE_COPY[object.objectType]}</span>
          {showState && <span className={`object-state severity-${object.state.severity}`}><i />{object.state.label}</span>}
        </header>
        <strong className="object-label">{object.name}</strong>
        {showSummary && <p className="object-summary">{object.summary || "尚无概述"}</p>}
        {showMetadata && (
          <footer className="object-metadata">
            <span>{technology || String(object.metadata.canonicalEntityType ?? TYPE_COPY[object.objectType])}</span>
            <span>{incomingCount} in · {outgoingCount} out</span>
          </footer>
        )}
        {flowSteps.length > 0 && (
          <div className="object-flow-steps" aria-label="Flow steps">
            {flowSteps.slice(0, 3).map((step) => (
              <span
                className={step.role === "entry" || step.role === "exit" ? `role-${step.role}` : ""}
                key={`${step.sequence}:${step.title}`}
                title={`${step.role} · ${step.title}`}
              >
                <b>{step.role === "entry" ? "▶" : step.role === "exit" ? "■" : step.sequence}</b>{step.title}
              </span>
            ))}
            {flowSteps.length > 3 && <em>+{flowSteps.length - 3}</em>}
          </div>
        )}
      </div>
    </article>
  );
}

