function syntheticCorridorRoute(
  id: string,
  sourceRect: LayoutRect,
  targetRect: LayoutRect,
  columnGapCenters: number[],
  rowGapCenters: number[],
): RelationshipRoute {
  const sourceRight = sourceRect.x + sourceRect.width;
  const targetLeft = targetRect.x;
  const sourceMidY = sourceRect.y + sourceRect.height / 2;
  const targetMidY = targetRect.y + targetRect.height / 2;
  const point = (x: number, y: number) => ({ x, y });

  if (targetLeft > sourceRight + 32) {
    const corridorX = nearestGapOf(columnGapCenters, sourceRight, targetLeft, (sourceRight + targetLeft) / 2);
    return {
      id,
      points: [point(sourceRight, sourceMidY), point(corridorX, sourceMidY), point(corridorX, targetMidY), point(targetLeft, targetMidY)],
      labelPoint: point(corridorX, (sourceMidY + targetMidY) / 2),
      sourceSide: "right",
      targetSide: "left",
      synthetic: true,
    };
  }

  const sourceBottom = sourceRect.y + sourceRect.height;
  const sourceMidX = sourceRect.x + sourceRect.width / 2;
  const targetMidX = targetRect.x + targetRect.width / 2;
