const fitReadableMap = useCallback(() => {
  const instance = instanceRef.current;
  if (!instance) return;
  const targets = instance.getNodes().filter((node) => node.type === "object");
  const options = { ...fitViewContract(), padding: targets.length > 0 ? 0.24 : fitViewContract().padding };
  if (targets.length > 0) void instance.fitView({ ...options, nodes: targets.map((node) => ({ id: node.id })) });
  else void instance.fitView(options);
}, []);

const fitOpeningFrame = useCallback(() => {
  const instance = instanceRef.current;
  if (!instance) return;
  const focusRegionId = defaultFocusRegion(graph, view);
  if (!focusRegionId) {
    fitReadableMap();
    return;
  }
  const visibleIds = visibleObjectIds(graph, view);
  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  const objectRegionById = new Map(graph.objects.map((object) => [object.id, object.regionId]));
  const withinFocusRegion = (objectId: string) => {
    let cursor: string | undefined = objectRegionById.get(objectId);
    const seen = new Set<string>();
    while (cursor && !seen.has(cursor)) {
      if (cursor === focusRegionId) return true;
      seen.add(cursor);
      cursor = regionById.get(cursor)?.parentRegionId;
    }
    return false;
  };
  const fitTargets = instance.getNodes().filter((node) =>
    (node.type === "region" && node.id === focusRegionId)
    || (node.type === "object" && visibleIds.has(node.id) && withinFocusRegion(node.id)));
  if (fitTargets.length > 1) void instance.fitView({ ...fitViewContract(), padding: 0.14, nodes: fitTargets.map((node) => ({ id: node.id })) });
  else fitReadableMap();
}, [fitReadableMap, graph, view]);

useEffect(() => {
  setNodes(projection.nodes);
  setEdges(projection.edges);
  const layoutIdentity = layout ? `${storageKey}:${layout.fingerprint}` : "";
  if (layoutIdentity && fittedLayoutRef.current !== layoutIdentity) {
    fittedLayoutRef.current = layoutIdentity;
    const timer = window.setTimeout(() => fitOpeningFrame(), 40);
    return () => window.clearTimeout(timer);
  }
  return undefined;

